    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Reject bins that cannot fit the item
    if bin_residual < item_size {
        return 1e6;
    }

    // Basic ratios
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let usage_ratio = 1.0 - waste_ratio;
    let residual_gap = bin_residual as i32 - item_size as i32;
    let residual_fraction = residual_gap.max(0) as f64 / bin_capacity as f64;
    let frag_ratio = if bin_residual > 0 {
        post_residual as f64 / bin_residual as f64
    } else {
        1.0
    };

    // Open bins penalty (logarithmic)
    let open_penalty = (open_bins_count as f64 + 1.0).ln() * 0.05;

    // Mean residual deviation penalty
    let mean_diff = (waste_ratio - mean_residual).abs() * 1.5;
    let mean_reward = if (waste_ratio - mean_residual).abs() < 0.015 { 0.02 } else { 0.0 };

    // Next item overflow penalties
    let next_overflow_penalty = if next_item_size > post_residual {
        let diff = next_item_size as f64 - post_residual as f64;
        (diff * diff / bin_capacity as f64) * 1.4
    } else {
        0.0
    };
    let next_residual_overflow_penalty = if next_item_size > bin_residual {
        let diff = next_item_size as f64 - bin_residual as f64;
        (diff / bin_capacity as f64) * 1.1
    } else {
        0.0
    };

    // Early stream penalty
    let early_factor = step_index as f64 / total_items.max(1) as f64;
    let early_penalty = 0.04 / (1.0 + (-4.5 * (early_factor - 0.3)).exp());

    // Fit availability & new bin penalties
    let fit_availability_penalty = if fitting_bins_count == 0 { 4.5 } else { 0.0 };
    let new_bin_penalty =
        if bin_residual == bin_capacity && fitting_bins_count > 0 { 3.2 } else { 0.0 };

    // Excess open bins penalty
    let frag_penalty = if open_bins_count > 10 {
        let excess = (open_bins_count - 10) as f64 / 3.0;
        excess * excess * 1.3
    } else {
        0.0
    };

    // Residual tightness reward
    let residual_tightness_reward = if residual_gap >= 0 && residual_gap <= item_size as i32 {
        (1.0 - residual_fraction) * 0.4
    } else {
        0.0
    };

    // Perfect fit bonus
    let perfect_fit_bonus = if residual_gap as u32 == next_item_size { 0.12 } else { 0.0 };

    // Tiny waste bonus
    let tiny_waste_bonus = if waste_ratio < 0.025 { 0.07 } else { 0.0 };

    // Look‑ahead overflow penalty (stronger)
    let lookahead_penalty = if next_item_size > residual_gap as u32 {
        let diff = next_item_size as f64 - residual_gap as f64;
        (diff / bin_capacity as f64) * 0.6
    } else {
        0.0
    };

    // Fragmentation penalty
    let frag_penalty_factor = frag_ratio * 0.25;

    // Aggregate score
    let mut score = 0.0;
    score += waste_ratio.powi(2) * 1.3;            // large waste is bad
    score += frag_penalty_factor;                  // fragmentation penalty
    score += open_penalty;                         // open bins penalty
    score += mean_diff;                            // deviation from mean waste
    score += next_overflow_penalty;                // next item overflow penalty
    score += next_residual_overflow_penalty;       // next item residual overflow
    score += early_penalty;                        // early‑stream penalty
    score += fit_availability_penalty;             // no fitting bins penalty
    score += new_bin_penalty;                      // new bin opening penalty
    score += frag_penalty;                         // excess open bins penalty
    score -= residual_tightness_reward;            // reward good fit
    score += tiny_waste_bonus;                     // reward near‑empty bins
    score += mean_reward;                          // reward closeness to mean waste
    score += lookahead_penalty;                    // look‑ahead overflow penalty
    score += perfect_fit_bonus;                    // perfect next‑item fit bonus

    // Final weighting with usage ratio
    score * 0.9 + 0.1 * usage_ratio
}

