    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic waste and usage
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let usage_ratio = 1.0 - waste_ratio;

    // Fragmentation after placement
    let frag_ratio = if bin_residual > 0 {
        post_residual as f64 / bin_residual as f64
    } else {
        1.0
    };

    // Open‑bin pressure
