        ((bin_residual - item_size * 2) as f64 / bin_capacity as f64) * 1.5
    } else {
        0.0
    };

    // Balance residuals with the mean
    let mean_residual_units = mean_residual * bin_capacity as f64;
    let balance_penalty = if post_residual as f64 > mean_residual_units * 1.1 {
        ((post_residual as f64 - mean_residual_units * 1.1) / bin_capacity as f64) * 4.0
    } else {
        0.0
    };

    // Compactness reward
    let compact_reward = (1.0 - waste_ratio).powi(3) * -0.04;

    // Look‑ahead penalties
