        ((next_item_size as f64 - post_residual as f64) / bin_capacity as f64) * 5.0
    } else {
        0.0
    };

    let curr_bin_fit_penalty = if next_item_size > bin_residual {
        ((next_item_size as f64 - bin_residual as f64) / bin_capacity as f64) * 3.5
    } else {
        0.0
    };

