        -(open_bins_count as f64).sqrt() * 0.015
    } else {
        0.0
    };

    // Open‑bin ratio penalty
    let open_ratio = open_bins_count as f64 / total_items.max(1) as f64;
    let open_ratio_penalty = if open_ratio > 0.10 {
        (open_ratio - 0.10) * 20.0
    } else {
        0.0
    };

    // Late‑stage penalty
    let step_reward = if step_index > total_items / 3 {
        -0.02
    } else {
        0.0
    };

    // Aggregate score
