    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic waste and usage ratios
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let usage_ratio = 1.0 - waste_ratio;

    // Base waste penalty weighted non‑linearly
    let mut score = waste_ratio.powf(1.15) * 1.20;
    // Deviation from the average residual
    score += (waste_ratio - mean_residual).abs() * 4.0;

    // Open‑bin penalty (logarithmic scaling)
    score += (open_bins_count as f64 + 1.0).ln() * 0.10;

    // Fit penalty: discourage bins that are the only fit
    if fitting_bins_count == 0 {
        score += 12.0;
    }

    // New‑bin penalty: bias against opening a new bin when many are open
    if bin_residual == bin_capacity {
        score += if open_bins_count > 7 { 2.0 } else { 5.0 };
    }

    // Look‑ahead penalty for the next item
    if next_item_size > post_residual {
        let waste_next = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 12.0 + 6.0 * waste_next;
    }

    // Gap penalty: how far the next item is from the current residual
    if bin_residual < next_item_size {
        score += ((next_item_size - bin_residual) as f64 / bin_capacity as f64) * 3.5;
    }

    // Early‑stage adjustment: prefer tighter packing early
    let early_factor = step_index as f64 / total_items.max(1) as f64;
    if early_factor < 0.25 {
        score += (0.25 - early_factor).powf(0.8) * 0.15;
    }

    // Fragmentation penalty for too many open bins
    if open_bins_count > 10 {
        score += ((open_bins_count as f64 - 10.0) / 4.0).powi(2) * 2.5;
    }

    // Perfect fit bonus (negative penalty)
    if post_residual == 0 {
        score -= 7.0;
    }

    // Residual closeness penalty for very small waste
    if waste_ratio > 0.92 {
        score += (waste_ratio - 0.92) * 18.0;
    }

    // Residual‑next penalty: how the current residual compares to the next item
    if bin_residual > 0 && bin_residual < next_item_size {
        score +=
            ((next_item_size - bin_residual) as f64 / next_item_size as f64) * 2.5;
    }

    // Final scaling: blend with usage ratio
    score = score * 0.92 + 0.08 * usage_ratio;
    score
